func TestExplainEarlierMissKeptLaterMatchWins(t *testing.T) {
	// 第一条规则因 tier 不命中而整体不成立：它仍要出现在解释里（含全部条件
	// 的逐条判断），求值继续到 r-allow 并命中。
	flag := explainFlag(t, "f")
