		t.Fatalf("unexpected result: %+v", got.EvalResult)
	}
	if ids := explainedIDs(got); len(ids) != 2 || ids[0] != "r-deny" || ids[1] != "r-allow" {
		t.Fatalf("both considered rules must be listed, got %v", ids)
	}
