		copy(list, c.inVal)
		ce.CompareValue = list
	default:
		// 解析阶段已拒绝未知运算符，防御性处理。
		ce.CompareValue = nil
	}
	v, present := ctx.Get(c.Attribute)
	if !present {
		ce.Missing = true
		ce.Match = false
		return ce
	}
	ce.ActualValue = &v
	ce.Match = c.compare(v)
	return ce
}

