package payflow

import (
	"strings"
	"testing"
)

func TestTmpPlainEvalAllocsIndependentOfInList(t *testing.T) {
	mkFlag := func(n int) *Flag {
		items := make([]string, n)
		for i := range items {
			items[i] = "x"
		}
		list := `["` + strings.Join(items, `","`) + `"]`
		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
			`{"id":"r1","value":true,"conditions":[{"attribute":"tier","op":"in","value":` + list + `}]}` +
			`]}]}`
		return mustParseConfig(t, cfg).Find("f")
	}
	ctx := mustParseContext(t, `{"tier":"nope"}`)
	small := testing.AllocsPerRun(50, func() { mkFlag(t, 3).Evaluate(ctx) })
	large := testing.AllocsPerRun(50, func() { mkFlag(t, 3000).Evaluate(ctx) })
	t.Logf("allocs: in-list 3 -> %v, in-list 3000 -> %v", small, large)
	if large != small {
		t.Fatalf("plain evaluation allocs grow with in-list length: %v -> %v", small, large)
	}
}
EOF
go test ./payflow -run TestTmpPlainEvalAllocsIndependentOfInList -v 2>&1 | tail -5; rm payflow/alloc_tmp_test.go

